/**
 * Query the predicted hand skeleton at `at_timestamp_ns`. Writes
 * `ALVR_OXR_HAND_JOINT_COUNT` joints into `out_joints` when the client has a
 * tracked hand on this side. Sets `*out_is_tracked = false` and leaves
 * `out_joints` untouched when the client reports `hand_skeletons[side] = None`
 * for the resolved frame.
 *
 * Sources the skeleton from `ServerCoreContext::get_hand_skeleton`, which
 * **ignores `at_timestamp_ns`** and returns the most recently received
 * `TrackingData.hand_skeletons[side]` sample. Quest hand samples are
 * timestamped in the client's predicted-display clock domain and there is no
 * client↔server time sync, so timestamp-based matching cannot align with the
 * PC-runtime clock that OpenXR callers query in. Staleness is bounded by the
 * Quest's send cadence (~10–16 ms). Joint order matches the
 * `XR_HAND_JOINT_*_EXT` enum 1:1 — the bridge does no reordering, so the
 * Monado-side `xrt_device::get_hand_tracking` can hand them straight to the
 * state tracker. Returns `NotInitialised` when the bridge isn't initialised;
 * otherwise `Ok` with `is_tracked` indicating whether real data was written.
 *
 * # Safety
 * `out_joints` must be a writable buffer of at least
 * `ALVR_OXR_HAND_JOINT_COUNT` elements. `out_is_tracked` must be writable.
 */
AlvrOxrResult alvr_oxr_get_hand_skeleton(AlvrOxrSide side,
                                         int64_t at_timestamp_ns,
                                         struct AlvrOxrHandJoint *out_joints,
                                         bool *out_is_tracked);

/**
 * Read the latest cached per-view foveation params. Drives the encoder side
 * inside [`alvr_oxr_submit_layers`]. Returns `Ok` with `is_present = false`
 * for both views when foveation is disabled session-wide or no update has
 * landed yet; the encoder should encode at full resolution in that case.
 *
 * # Safety
 * `out_views` must be a writable buffer of 2 [`AlvrOxrFoveationView`]s
 * (left = index 0, right = index 1).
 */
AlvrOxrResult alvr_oxr_get_foveation(struct AlvrOxrFoveationView *out_views);

/**
 * Push a new per-view foveation update into the bridge. Called by the
 * `server_core` drain thread when a new `ServerCoreEvent::PerViewFoveation`
 * arrives (which itself is fed by either an eye-tracking → foveation-centre
 * worker or a future `RealTimeConfig.per_view_foveation` field).
 *
 * # Safety
 * `views` must point to 2 [`AlvrOxrFoveationView`]s. Caller retains ownership;
 * the bridge copies into its internal cache.
 */
AlvrOxrResult alvr_oxr_set_foveation(const struct AlvrOxrFoveationView *views);

/**
 * Submit a frame's worth of composition layers.
 *
 * Forwards the projection layer (`layers[0]`) to the NVENC encoder via
 * [`encoder_bridge`]; encoded NALs flow back through `server_core::send_video_nal`
 * from the encoder's packet callback. Non-projection layers are squashed into
 * the projection image by `comp_alvr` before this call, so only `layers[0]` is
 * read here.
 *
 * Returns `Ok` when the frame was encoded, `Failed` when it was dropped (e.g.
 * the encoder isn't up or the external-memory import failed). Never
 * `NotImplemented` now that the body is wired.
 *
 * `display_time_ns` is the frame's predicted display time (Monado-monotonic
 * nanoseconds); the encoded NALs carry it so the client can match the frame to
 * a tracking pose.
 *
 * # Safety
 * `layers` must point to `layer_count` valid `AlvrOxrLayer`s. `sync_handle`
 * may be 0 to indicate "no GPU sync, use a fence".
 */
AlvrOxrResult alvr_oxr_submit_layers(int64_t frame_id,
                                     uint32_t layer_count,
                                     const struct AlvrOxrLayer *layers,
                                     uint64_t sync_handle,
                                     int64_t display_time_ns);

/**
 * Report per-frame compositor pacing timestamps for telemetry.
 *
 * Called by the Monado-side `comp_alvr` after the `layer_commit` pacing
 * markers fire (matches `u_pc_mark_point` semantics):
 * - `begin_ns` — start of compositor work for this frame
 *   (`U_TIMING_POINT_BEGIN`).
 * - `submit_begin_ns` — moment work is handed to the GPU/encoder, i.e.
 *   just before [`alvr_oxr_submit_layers`] (`U_TIMING_POINT_SUBMIT_BEGIN`).
 * - `submit_end_ns` — moment the handoff completed
 *   (`U_TIMING_POINT_SUBMIT_END`).
 *
 * All timestamps are in nanoseconds from the same monotonic clock used by
 * `u_pacing` (`os_monotonic_get_ns()`). The bridge intentionally accepts
 * raw timestamps rather than pre-computed deltas so the Rust side can build
 * any window/aggregation shape it likes.
 *
 * Forwards the sample into `alvr_server_core`'s metrics exporter via
 * [`ServerCoreContext::report_oxr_pacing`]. The metrics aggregator
 * derives CPU and submit durations and exports them in the standard
 * per-window snapshot under the `oxr_pacing` field. Drops silently when
 * no client is connected (no metrics sender wired up yet) or when the
 * bridge context is not initialised. Always returns `Ok` so the
 * compositor doesn't log a per-frame failure.
 *
 * # Safety
 * Always safe to call. Takes only `Copy` POD values.
 */
AlvrOxrResult alvr_oxr_report_pacing(int64_t frame_id,
                                     int64_t begin_ns,
                                     int64_t submit_begin_ns,
                                     int64_t submit_end_ns);

/**
 * Report per-frame counts of non-projection layers the compositor saw.
 *
 * `comp_alvr` currently passes only `XRT_LAYER_PROJECTION` /
 * `XRT_LAYER_PROJECTION_DEPTH` layers to the encoder and drops everything
 * else. This entrypoint lets it report what was dropped so the metrics
 * exporter can surface "what kinds of overlays do real apps actually
 * submit" — a useful prior for Phase 7 rasterisation work (build quad
 * support first if most apps submit quads, etc.).
 *
 * Each `n_*` count is the number of layers of that type on this single
 * frame. Frame-id is taken purely so future versions can correlate with
 * the pacing sample for the same frame; the current aggregator does not
 * retain it.
 *
 * Always returns `Ok`. Drops silently when no client is connected.
 *
 * # Safety
 * Always safe to call. Takes only `Copy` POD values.
 */
AlvrOxrResult alvr_oxr_report_layer_types(int64_t frame_id,
                                          uint32_t n_quad,
                                          uint32_t n_cylinder,
                                          uint32_t n_equirect,
                                          uint32_t n_cube,
                                          uint32_t n_passthrough);

/**
 * Poll one session event from the bridge. Returns
 * [`AlvrOxrResult::Ok`] with `out_event.event_type == None` when the queue
 * is empty.
 *
 * # Safety
 * `out_event` must be a writable `AlvrOxrEvent`.
 */
AlvrOxrResult alvr_oxr_poll_session_event(struct AlvrOxrEvent *out_event);

